// Parse Google Sheets gviz response
const raw = $input.first().json.data || $input.first().json.body || '';
const rawStr = typeof raw === 'string' ? raw : JSON.stringify(raw);
let alerts = [];
try {
  const match = rawStr.match(/google\.visualization\.Query\.setResponse\(([\s\S]*?)\);/);
  if (match) {
    const json = JSON.parse(match[1]);
    const cols = json.table.cols.map(c => c.label);
    alerts = json.table.rows.map(row => {
      const obj = {};
      row.c.forEach((cell, i) => { obj[cols[i]] = cell ? (cell.v || cell.f || '') : ''; });
      return obj;
    }).filter(a => a.Timestamp);
  }
} catch(e) { /* fallback: no data */ }

// Build context from alerts
const total = alerts.length;
const anomalies = alerts.filter(a => a.Anomaly && a.Anomaly !== 'NORMAL');
const critical = anomalies.filter(a => a.Severity === 'CRITICAL').length;
const high = anomalies.filter(a => a.Severity === 'HIGH').length;
const medium = anomalies.filter(a => a.Severity === 'MEDIUM').length;
const autonomous = alerts.filter(a => a.Escalation === 'AUTONOMOUS').length;
const humanReview = alerts.filter(a => a.Escalation === 'HUMAN_REVIEW').length;
const escalated = alerts.filter(a => a.Escalation === 'ESCALATED').length;

// Node stats
const nodeStats = {};
alerts.forEach(a => {
  const n = a.Node || 'Unknown';
  if (!nodeStats[n]) nodeStats[n] = { total: 0, anomalies: 0, types: {} };
  nodeStats[n].total++;
  if (a.Anomaly && a.Anomaly !== 'NORMAL') {
    nodeStats[n].anomalies++;
    nodeStats[n].types[a.Anomaly] = (nodeStats[n].types[a.Anomaly] || 0) + 1;
  }
});

const nodeReport = Object.entries(nodeStats).map(([node, s]) => 
  `${node}: ${s.total} olay, ${s.anomalies} anomali ${Object.entries(s.types).map(([t,c]) => `${t}(${c})`).join(', ')}`
).join('\n');

// Recent 10 alerts for detail
const recent = [...alerts].reverse().slice(0, 10).map(a => 
  `[${a.Timestamp}] ${a.Node} | ${a.Anomaly} | ${a.Severity} | Güven:${a.Confidence} | ${a.Escalation} | ${a['Healing Action'] || '-'}`
).join('\n');

// Get original webhook body
const webhookData = $('Chat Webhook').first().json.body || $('Chat Webhook').first().json;
const userMessage = webhookData.message || '';
const sessionId = webhookData.sessionId || 'dashboard';

const sheetsContext = `## GÜNCEL AĞ VERİLERİ (Google Sheets - ${new Date().toISOString()})
Toplam Olay: ${total} | Anomali: ${anomalies.length} | KRİTİK: ${critical} | YÜKSEK: ${high} | ORTA: ${medium}
Otonom Aksiyon: ${autonomous} | İnsan Onayı: ${humanReview} | Eskalasyon: ${escalated}

### Node Bazlı Durum:
${nodeReport}

### Son 10 Olay (en yeniden eskiye):
${recent}`;

return [{ json: { userMessage, sessionId, sheetsContext } }];

